function lcaGeneralImpl(root, p, q) {
  if (!root) return null;
  if (root === p || root === q) return root;
  const left = lcaGeneralImpl(root.left, p, q);
  const right = lcaGeneralImpl(root.right, p, q);
  if (left && right) return root;
  return left || right;
}

function lcaBSTImpl(root, p, q) {
  if (!root) return null;
  if (p.val < root.val && q.val < root.val) return lcaBSTImpl(root.left, p, q);
  if (p.val > root.val && q.val > root.val) return lcaBSTImpl(root.right, p, q);
  return root;
}

function lcaBSTIterativeImpl(root, p, q) {
  let curr = root;
  while (curr) {
    if (p.val < curr.val && q.val < curr.val) curr = curr.left;
    else if (p.val > curr.val && q.val > curr.val) curr = curr.right;
    else return curr;
  }
  return null;
}

function allBSTLCAsAgree(root, p, q) {
  const a = lcaBSTImpl(root, p, q);
  const b = lcaBSTIterativeImpl(root, p, q);
  return a && b && a.val === b.val;
}

