function serializeImpl(root) {
  const parts = [];
  function dfs(node) {
    if (!node) { parts.push('null'); return; }
    parts.push(String(node.val));
    dfs(node.left);
    dfs(node.right);
  }
  dfs(root);
  return parts.join(',');
}

function deserializeImpl(data) {
  const vals = data.split(',');
  let i = 0;
  function build() {
    if (vals[i] === 'null') { i++; return null; }
    const node = new TreeNode(Number(vals[i++]));
    node.left = build();
    node.right = build();
    return node;
  }
  return build();
}

function roundTripVerify(root) {
  const s1 = serializeImpl(root);
  const s2 = serializeImpl(deserializeImpl(s1));
  return s1 === s2;
}

