class TreeNode {
  constructor(val,left=null,right=null){this.val=val;this.left=left;this.right=right;}
}

function buildBST(values) {
  function ins(r,v){if(!r)return new TreeNode(v);if(v<r.val)r.left=ins(r.left,v);else r.right=ins(r.right,v);return r;}
  let r=null; for(const v of values) r=ins(r,v); return r;
}

function kthSmallestImpl(root, k) {
  let count = 0, result = null;
  function inorder(node) {
    if (!node || result !== null) return;
    inorder(node.left);
    count++;
    if (count === k) { result = node.val; return; }
    inorder(node.right);
  }
  inorder(root);
  return result;
}

function kthSmallestIterativeImpl(root, k) {
  const stack = [];
  let curr = root;
  while (curr || stack.length) {
    while (curr) { stack.push(curr); curr = curr.left; }
    curr = stack.pop();
    if (--k === 0) return curr.val;
    curr = curr.right;
  }
  return -1;
}

class BSTIteratorImpl {
  constructor(root) { this.stack = []; this._pushLeft(root); }
  _pushLeft(node) { while (node) { this.stack.push(node); node = node.left; } }
  next() { const node = this.stack.pop(); this._pushLeft(node.right); return node.val; }
  hasNext() { return this.stack.length > 0; }
}

