    let node = this.root;
    for (const char of prefix) {
      if (!node.children.has(char)) return [];
      node = node.children.get(char);
    }
    const results = [];
    function dfs(curr, currentWord) {
      if (curr.isEnd) results.push(currentWord);
      for (const [char, child] of curr.children) dfs(child, currentWord + char);
