function findWordsImpl(board, words) {
  const root = new TrieNode();
  for (const word of words) {
    let node = root;
    for (const char of word) {
      if (!node.children.has(char)) node.children.set(char, new TrieNode());
      node = node.children.get(char);
    }
    node.isEnd = word;
  }
  const m = board.length, n = board[0].length, result = [];
  const DIRS = [[0,1],[0,-1],[1,0],[-1,0]];
  function dfs(row, col, trieNode) {
    const char = board[row][col];
    if (!trieNode.children.has(char)) return;
    const nextNode = trieNode.children.get(char);
    if (nextNode.isEnd) { result.push(nextNode.isEnd); nextNode.isEnd = false; }
    board[row][col] = '#';
    for (const [dr, dc] of DIRS) {
      const r = row+dr, c = col+dc;
      if (r>=0&&r<m&&c>=0&&c<n&&board[r][c]!=='#') dfs(r, c, nextNode);
    }
    board[row][col] = char;
    if (nextNode.children.size === 0) trieNode.children.delete(char);
  }
  for (let r=0;r<m;r++) for (let c=0;c<n;c++) dfs(r,c,root);
  return result;
}

